export interface RuntimeConfig {
  /** Stamp layer; false in production until the Harzer Wandernadel office has agreed (STAMPS_ENABLED). */
  stampsEnabled: boolean;
}

/** Reads /config.json (generated by the web container or the Vite dev server). Fails closed. */
export async function loadRuntimeConfig(): Promise<RuntimeConfig> {
  try {
    const response = await fetch("/config.json", { cache: "no-store" });
    if (!response.ok) return { stampsEnabled: false };
    const data = (await response.json()) as Partial<RuntimeConfig>;
    return { stampsEnabled: data.stampsEnabled === true };
  } catch {
    return { stampsEnabled: false };
  }
}
